sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var ad = new x_fed_day2_ops.AdHybridClient();
  var unclassified = [null, undefined, {}, { onPremisesSyncEnabled: null }, { onPremisesSyncEnabled: 'true' }];
  for (var i = 0; i < unclassified.length; i++) {
    if (ad.isAdMastered(unclassified[i]) !== false) {
      stepResult.setFailed('an unclassifiable object was treated as AD-mastered (case ' + i + ') - must fail closed, not write to AD');
      return;
    }
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
